       k(STOP2, clip='skidStop', blend=0.03), k(STOP2, toon={'hip': 0, 'sq': [1.12, 0.88, 1.12], 'hairUp': 0.6, 'face': {**HFD, 'eye': 0.3}}, toonDur=0.04),
