# ============================== the removal men and the piano: one world prop carried between them; the floor under any point of the stairwell
def FLOOR(x, z, k_):
    # the walking height at (x, z) around floor k_: landing k_ (x >= 1.4), flight A_k_ (front), flight B_{k_-1} (back), else the landing's height
    if x >= 1.4: return FH * k_
    if z > 0.45: return r(FH * k_ + 0.09 + 0.5 * (1.4 - min(1.4, max(-1.4, x))))
    if z < -0.45: return r(FH * (k_ - 1) + 1.4 + 0.09 + 0.5 * (min(1.4, max(-1.4, x)) + 1.4))
    return FH * k_
def CARRY(path, t0, dur, k_, n=10, gap=1.05, lift=0.62):
    # samples a polyline: the piano's centre and heading at each step; the front man `gap` ahead along the heading, the back one behind; heights from FLOOR
    L_ = [math.dist(path[i][::2], path[i + 1][::2]) for i in range(len(path) - 1)]; tot = sum(L_)
    def at_(u):
        d = u * tot
        for i, l in enumerate(L_):
            if d <= l or i == len(L_) - 1:
                a, b = path[i], path[i + 1]; w = min(1.0, d / l) if l else 0
                return [a[0] + (b[0] - a[0]) * w, a[2] + (b[2] - a[2]) * w], math.degrees(math.atan2(b[0] - a[0], b[2] - a[2]))
            d -= l
    out = []
    for j in range(n + 1):
        u = j / n; (x, z), hd = at_(u); F = fwd(hd)
        fx, fz, bx, bz = x + F[0] * gap, z + F[2] * gap, x - F[0] * gap, z - F[2] * gap
        yc = max(FLOOR(x - 0.7 * F[0], z - 0.7 * F[2], k_), FLOOR(x + 0.7 * F[0], z + 0.7 * F[2], k_), FLOOR(x, z, k_))
        out.append({'t': r(t0 + dur * u), 'c': [r(x), r(yc + lift), r(z)], 'hd': r(hd, 1), 'f': [r(fx), FLOOR(fx, fz, k_), r(fz)], 'b': [r(bx), FLOOR(bx, bz, k_), r(bz)]})
    return out
def CARRY_KEYS(S, extra_prop_keys=()):
    # the piano's keys (position and heading) and both men's keys (paths, hands on the piano's ends, legs a blur)
    pk = [k(S[0]['t'], to=S[0]['c'], dur=0.0)]
    for a, b in zip(S, S[1:]): pk += [k(a['t'], to=b['c'], dur=r(b['t'] - a['t']), ease='linear'), k(a['t'], rotTo=[0.0, r(math.radians(b['hd'] + 90), 4), 0.0], dur=r(b['t'] - a['t']), ease='linear')]
    mk = {}
    for who, end, sgn in (('d1', 'f', 1), ('d2', 'b', -1)):
        ks = [k(S[0]['t'], path=[s_[end] for s_ in S], dur=r(S[-1]['t'] - S[0]['t']), clip='run', ease='linear', speed=1.5)]
        for s_ in S:
            F = fwd(s_['hd']); R_ = right(s_['hd']); c = s_['c']
            # both mittens on the piano's near end, at its mid height, either side of it
            e = [c[0] + sgn * F[0] * 0.78, c[1] + 0.55, c[2] + sgn * F[2] * 0.78]
            hr = add(e, [R_[0] * 0.28, 0, R_[2] * 0.28]); hl = add(e, [-R_[0] * 0.28, 0, -R_[2] * 0.28])
            ks.append(k(s_['t'], toon={**HAND(hr, hl, 'grip', 'grip', hose=0.15), 'autoSq': 0.3, 'smear': 0.6, 'bend': {'spine': [0.2, 0, 0, 1, None]}, 'face': {'lid': 0.0, 'mouth': 'clench', 'brow': -0.6}}, toonDur=r(max(0.03, (S[1]['t'] - S[0]['t']) * 0.9))))
        mk[who] = ks
    return pk, mk
