def CLIMB(steps, t0_, dt, ry, tilt=TT):
    # one step at a time: a little push down, up, a squash on the next step; the trolley follows a beat later, a step lower, and bumps
    ak, tk, bumps = [], [], []
    for j in range(1, len(steps)):
        t_ = r(t0_ + dt * (j - 1))
        ak += [k(t_, to=steps[j], dur=r(dt * 0.4), ease='inOut', glide=True, face=ry),
               k(r(t_ - 0.06), toon={**VTT, 'sq': [1.05, 0.95, 1.05], 'face': VF}, toonDur=0.05), k(t_, toon={**VTT, 'sq': [0.96, 1.05, 0.96], 'face': VF}, toonDur=0.06),
               k(r(t_ + dt * 0.4), toon={**VTT, 'sq': [1.04, 0.96, 1.04], 'face': VF}, toonDur=0.04), k(r(t_ + dt * 0.4 + 0.1), toon={**VTT, 'face': VF}, toonDur=0.08)]
        tp = off(steps[j - 1], ry, -0.42); tk.append(k(r(t_ + 0.14), to=tp, dur=0.14, ease='inOut')); bumps.append(r(t_ + 0.14))
    return ak, tk, bumps
